# bash completion for kgdiff. Generated by `kgdiff completion bash`.
#
#   eval "$(kgdiff completion bash)"        # in ~/.bashrc, or, with bash-completion 2:
#   kgdiff completion bash > ~/.local/share/bash-completion/completions/kgdiff

_kgdiff_files() {
    local IFS=$'\n'
    compopt -o filenames 2>/dev/null
    COMPREPLY+=($(compgen -f -- "$cur"))
}

_kgdiff() {
    local cur prev cmd
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    # --option=value arrives as three words (--option, = and value) in bash 4 and later, and
    # as one in bash 3.2, where readline still replaces only what follows the =.
    if [[ "$cur" == "=" ]]; then
        cur=""
    elif [[ "$prev" == "=" && $COMP_CWORD -ge 2 ]]; then
        prev="${COMP_WORDS[COMP_CWORD-2]}"
    elif [[ "$cur" == --*=* ]]; then
        prev="${cur%%=*}"
        cur="${cur#*=}"
    fi
    cmd=diff
    if [[ $COMP_CWORD -gt 1 ]]; then
        case "${COMP_WORDS[1]}" in
            apply|help|completion) cmd="${COMP_WORDS[1]}" ;;
        esac
    fi

    case "$cmd:$prev" in
        diff:--color)
            COMPREPLY=($(compgen -W "auto always never" -- "$cur"))
            return ;;
        diff:--locale)
            COMPREPLY=($(compgen -W "en zh-CN" -- "$cur"))
            return ;;
        diff:--lang|diff:--threshold|diff:--hierarchy|diff:--ignore-attr|diff:--title|diff:--panels|diff:--limit|diff:--watch-attr)
            return ;;
        diff:--html|diff:-o)
            _kgdiff_files
            return ;;
        diff:--format|diff:-f|diff:--before-format|diff:--after-format)
            COMPREPLY=($(compgen -W "auto json jsonld turtle ntriples nquads trig rdfxml obo graphml gexf" -- "$cur"))
            return ;;
        diff:--match)
            COMPREPLY=($(compgen -W "id auto similarity" -- "$cur"))
            return ;;
        diff:--edge-identity)
            COMPREPLY=($(compgen -W "structure id" -- "$cur"))
            return ;;
        diff:--theme)
            COMPREPLY=($(compgen -W "auto light dark" -- "$cur"))
            return ;;
        diff:--mode)
            COMPREPLY=($(compgen -W "overlay swipe replay changes" -- "$cur"))
            return ;;
        diff:--scope)
            COMPREPLY=($(compgen -W "all changes" -- "$cur"))
            return ;;
        apply:--color)
            COMPREPLY=($(compgen -W "auto always never" -- "$cur"))
            return ;;
        apply:--locale)
            COMPREPLY=($(compgen -W "en zh-CN" -- "$cur"))
            return ;;
        apply:--lang)
            return ;;
        apply:--output|apply:-o)
            _kgdiff_files
            return ;;
        apply:--format|apply:-f)
            COMPREPLY=($(compgen -W "auto json jsonld turtle ntriples nquads trig rdfxml obo graphml gexf" -- "$cur"))
            return ;;
        help:--color)
            COMPREPLY=($(compgen -W "auto always never" -- "$cur"))
            return ;;
        completion:--color)
            COMPREPLY=($(compgen -W "auto always never" -- "$cur"))
            return ;;
    esac

    if [[ "$cur" == -* ]]; then
        case "$cmd" in
            diff) COMPREPLY=($(compgen -W "--help -h --version -v --quiet -q --color --locale --lang --pretty --stat --name-status --json --delta --markdown --html -o --open --format -f --before-format --after-format --match --threshold --edge-identity --hierarchy --ignore-attr --no-merges --no-splits --title --theme --mode --scope --panels --reproducible --no-compute --allow-empty --exit-code --limit --watch-attr" -- "$cur")) ;;
            apply) COMPREPLY=($(compgen -W "--help -h --version -v --quiet -q --color --locale --lang --pretty --output -o --format -f --no-strict --verify-target --allow-empty --verbose" -- "$cur")) ;;
            help) COMPREPLY=($(compgen -W "--color" -- "$cur")) ;;
            completion) COMPREPLY=($(compgen -W "--help -h --color" -- "$cur")) ;;
        esac
        return
    fi

    case "$cmd" in
        help) [[ $COMP_CWORD -eq 2 ]] && COMPREPLY=($(compgen -W "apply completion" -- "$cur")) ;;
        completion) [[ $COMP_CWORD -eq 2 ]] && COMPREPLY=($(compgen -W "bash zsh fish" -- "$cur")) ;;
        *)
            [[ $COMP_CWORD -eq 1 ]] && COMPREPLY=($(compgen -W "apply help completion" -- "$cur"))
            _kgdiff_files ;;
    esac
}

# bash 3.2 has no compopt: there, file names are quoted and directories get their slash only
# when the whole completion is declared as one of file names.
if type compopt >/dev/null 2>&1; then
    complete -F _kgdiff kgdiff
else
    complete -o filenames -F _kgdiff kgdiff
fi
